    (re.compile(r'new (cto|cmo|cfo|coo|cro|vp|chief)|welcome our new|joining as (vp|director|head|chief)', re.IGNORECASE), 'new_cro_cco_hired'),
    (re.compile(r'series [a-e]|raised \$|funding round|seed round|venture capital|capital raise|fundrais', re.IGNORECASE), 'raised_new_funding_round'),
    (re.compile(r'leaving|departed|moved on from|last day at|farewell', re.IGNORECASE), 'champion_leaves_customer'),
    (re.compile(r'sounds great|interested|let\'s (chat|talk|connect|meet)|tell me more', re.IGNORECASE), 'positive_reply_sentiment'),
    (re.compile(r'onboarding complete|fully set up|first workflow|getting started with', re.IGNORECASE), 'trial_completes_onboarding_checklist'),
    (re.compile(r'pilot|poc|proof of concept|trial run|evaluation|testing your', re.IGNORECASE), 'requests_pilot_or_poc'),
    (re.compile(r'\broi\b|return on investment|business case|cost.benefit|payback period', re.IGNORECASE), 'asks_for_roi_model'),
    (re.compile(r'crossed \$|revenue milestone|arr.*(million|billion)|mrr growth', re.IGNORECASE), 'new_icp_company_created_via_data'),
    (re.compile(r'installed salesforce|salesforce (migration|implementation|setup)', re.IGNORECASE), 'installed_salesforce'),
    (re.compile(r'installed hubspot|hubspot (migration|implementation|setup)', re.IGNORECASE), 'installed_hubspot'),
    (re.compile(r'installed outreach|outreach\.io|salesloft', re.IGNORECASE), 'installed_outreach'),
    (re.compile(r'spreadsheet.*(crm|tracking|pipeline)|using (excel|sheets).*(crm|pipeline)', re.IGNORECASE), 'uses_adjacent_competitor'),
    (re.compile(r'ai (stack|tools|platform)|multiple ai|ai.native|ai-first', re.IGNORECASE), 'icp_account_uses_many_ai_tools'),
    (re.compile(r'pricing page|check.* pricing|how much does', re.IGNORECASE), 'viewed_pricing_page'),
    (re.compile(r'signed up.*haven\'t|trial.*no activity|created account.*but', re.IGNORECASE), 'free_trial_signup'),
