def classify_signal(post_text: str, signal_type: str = "social_post") -> Dict[str, str]:
    """Classify a post against the 224-signal taxonomy using keyword matching.

    Returns dict with signal_name, why, category, strength, funnel_stage, trigger_type.
    """
    if not post_text:
        return {
            "signal_name": "unknown", "category": "Sales-Led", "strength": "Low",
            "funnel_stage": "Awareness", "trigger_type": "Behavioral",
            "why": "No post text to classify",
        }

    for pattern, signal_key in _KEYWORD_PATTERNS:
        if pattern.search(post_text):
            entry = SIGNAL_TAXONOMY.get(signal_key)
            if entry:
                return {"signal_name": signal_key, **entry}

    return {
        "signal_name": "unknown", "category": "Sales-Led", "strength": "Low",
        "funnel_stage": "Awareness", "trigger_type": "Behavioral",
        "why": "No matching signal pattern found in post text",
    }


def get_signal_entry(key: str) -> Optional[Dict[str, str]]:
    return SIGNAL_TAXONOMY.get(key)


def list_signals_by_category(category: str) -> List[str]:
    return [k for k, v in SIGNAL_TAXONOMY.items() if v["category"] == category]


def list_signals_by_strength(strength: str) -> List[str]:
    return [k for k, v in SIGNAL_TAXONOMY.items() if v["strength"] == strength]


def list_signals_by_funnel_stage(stage: str) -> List[str]:
    return [k for k, v in SIGNAL_TAXONOMY.items() if v["funnel_stage"] == stage]
